<?php $top = max(1, ...array_values($funnel ?: [1])); ?>
<div class="stats"><div class="stat"><b><?= array_sum($funnel) ?></b><span>Applications (90 days)</span></div><div class="stat"><b><?= $tth !== null ? $tth . ' d' : '—' ?></b><span>Average days to hire</span></div><div class="stat"><b><?= (int) ($funnel['Hired'] ?? 0) ?></b><span>Hired</span></div></div>
<div class="two-eq"><div class="panel"><div class="panel-h">Funnel — last 90 days</div><div class="panel-b"><?php foreach (ATS_STAGES as $s): $n = (int) ($funnel[$s] ?? 0); ?><div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between" class="small"><span><?= e($s) ?></span><strong><?= $n ?></strong></div><div class="progress"><i style="width:<?= round($n * 100 / $top) ?>%"></i></div></div><?php endforeach; ?></div></div>
<div class="panel"><div class="panel-h">Where candidates come from</div><div class="panel-b"><?php foreach ($sources as $s): ?><p class="small" style="display:flex;justify-content:space-between;margin:0 0 8px"><span><?= e($s['source'] ?: 'Unknown') ?></span><strong><?= (int) $s['n'] ?></strong></p><?php endforeach; if (!$sources) { echo '<span class="muted small">No data yet.</span>'; } ?></div></div></div>
<div class="panel"><div class="panel-h">By vacancy</div><div class="table-wrap" style="border:0"><table class="t"><thead><tr><th>Vacancy</th><th>Status</th><th class="num">Applicants</th><th class="num">Avg fit</th><th class="num">Interview</th><th class="num">Offer</th><th class="num">Hired</th></tr></thead><tbody><?php foreach ($perJob as $j): ?><tr><td><a href="<?= e(url('/admin/ats', ['job' => $j['id']])) ?>"><?= e($j['title']) ?></a></td><td><?= badge($j['status']) ?></td><td class="num"><?= (int) $j['apps'] ?></td><td class="num"><?= $j['fit'] !== null ? (int) $j['fit'] . '%' : '—' ?></td><td class="num"><?= (int) $j['iv'] ?></td><td class="num"><?= (int) $j['off'] ?></td><td class="num"><?= (int) $j['hired'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
